/// // Define the global.
/// llvm.mlir.global @const(42 : i32) : i32
///
/// // Define an alias.
/// llvm.mlir.alias @const_alias : i32 {
///   %0 = llvm.mlir.addressof @const : !llvm.ptr
///   llvm.return %0 : !llvm.ptr
