/// llvm.mlir.global private @g() : !llvm.ptr {
///   %0 = llvm.blockaddress <function = @fn, tag = <id = 0>> : !llvm.ptr
///   llvm.return %0 : !llvm.ptr
/// }
///
/// llvm.func @fn() {
///   llvm.br ^bb1
/// ^bb1:  // pred: ^bb0
///   llvm.blocktag <id = 0>
